		panic(err)
	}
	fmt.Println(data.Keys()) // [SERVER_ID SERVER_ID_2]
}

type ParseOptions struct {
	Filename      string        // used in error messages
	DuplicateKeys DuplicateKeys // DuplicateError (default), DuplicateFirst, DuplicateLast
}

